def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    width = len(grid[0])
    # Fill zeros lying between adjacent markers in each row. The demo
    # illustrates downward-expanding triangular bands bounded by marker pairs.
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value != 0]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                if row[c] == 0:
                    out[r][c] = 2
    return out

